15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    /** Region -> inclusive 4-digit postcode range {low, high}. */
19	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
20	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
21	
22	    /** Fixed region -> IANA timezone table. */
23	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
24	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
25	
26	    private OwnerLocality() {
27	    }
28	
29	    /**
30	     * Return the canonical region for {@code city}, or {@code "UNKNOWN"} when the city is
31	     * null or not present in the table.
32	     */
33	    public static String forCity(String city) {
34	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
35	    }
36	
37	    /**
38	     * Return the canonical region, preferring the {@code postcode}: if it is a 4-digit code
39	     * that falls inside a known region's range, that region is returned; otherwise fall back
40	     * to the city-to-region table. Returns {@code "UNKNOWN"} when neither resolves a region.
41	     */
42	    public static String forCityAndPostcode(String city, String postcode) {
43	        String byPostcode = forPostcode(postcode);
44	        return byPostcode != null ? byPostcode : forCity(city);
45	    }
46	
47	    /**
48	     * Return the canonical region derived from the {@code postcode} alone (NSW 2000-2099,
49	     * VIC 3000-3099, QLD 4000-4099), or {@code "UNKNOWN"} when the postcode is absent,
50	     * malformed, or in no known range. This is the REGION component of an owner's
51	     * {@code customerCode}.
52	     */
53	    public static String forPostcodeOrUnknown(String postcode) {
54	        String region = forPostcode(postcode);
55	        return region != null ? region : "UNKNOWN";
56	    }
57	
58	    /**
59	     * Return the REGION component of a {@code customerCode} formatted {@code '<REGION>-<HASH8>'},
60	     * i.e. the text before the first {@code '-'}. Returns {@code "UNKNOWN"} when the customer
61	     * code is null or carries no region prefix. This is the owner's derived {@code locality}.
62	     */
63	    public static String regionFromCustomerCode(String customerCode) {
64	        if (customerCode == null) {
65	            return "UNKNOWN";
66	        }
67	        int dash = customerCode.indexOf('-');
68	        return dash > 0 ? customerCode.substring(0, dash) : "UNKNOWN";
69	    }
70	
71	    /**
72	     * Return the IANA timezone name for the owner's {@code customerCode}, derived from its
73	     * REGION component via the fixed region-to-timezone table (NSW -> Australia/Sydney,
74	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). Returns {@code null} when the
75	     * region is unknown, so the {@code timezone} field is omitted from the response.
76	     */
77	    public static String timezoneFromCustomerCode(String customerCode) {
78	        return REGION_TIMEZONE.get(regionFromCustomerCode(customerCode));
79	    }
80	
81	    /**
82	     * Compute the single Luhn check digit (0-9) over the digits contained in {@code s}.
83	     * Non-digit characters are ignored; the rightmost digit is doubled first. Kept here,
84	     * alongside the other derived-field helpers, so MapStruct does not treat it as an
85	     * implicit mapping method.
86	     */
87	    public static int luhn(String s) {
88	        int sum = 0;
89	        boolean dbl = true;
90	        for (int i = s.length() - 1; i >= 0; i--) {
91	            char c = s.charAt(i);
92	            if (c < '0' || c > '9') {
93	                continue;
94	            }
95	            int d = c - '0';
96	            if (dbl) {
97	                d *= 2;
98	                if (d > 9) {
99	                    d -= 9;
100	                }
101	            }
102	            sum += d;
103	            dbl = !dbl;
104	        }
105	        return (10 - (sum % 10)) % 10;
106	    }
107	
