109	     * Return the canonical region whose postcode range contains {@code postcode}, or
110	     * {@code null} when the postcode is absent, malformed, or in no known range.
111	     */
112	    private static String forPostcode(String postcode) {
113	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
114	            return null;
115	        }
116	        int value = Integer.parseInt(postcode);
117	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
118	            int[] range = entry.getValue();
119	            if (value >= range[0] && value <= range[1]) {
120	                return entry.getKey();
121	            }
