321	    /**
322	     * Counts how many existing owners live in the given city, compared case-insensitively.
323	     * This is evaluated before the new owner is persisted, so the owner being created is not
324	     * included in the count.
325	     *
326	     * @param city the new owner's city
327	     * @return the number of existing owners in that city
328	     */
329	    private int countOwnersInCity(String city) {
330	        int count = 0;
331	        for (Owner existing : this.clinicService.findAllOwners()) {
