364	    /**
365	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
366	     * registrationDate} rolls forward to the same business day. This is evaluated before the
367	     * new owner is persisted, so the owner being created is not included in the count.
368	     *
369	     * @param businessDay the adjusted business day to count against
370	     * @return the number of existing owners registered on that business day
371	     */
372	    private int countOwnersRegisteredOn(LocalDate businessDay) {
373	        int count = 0;
374	        for (Owner existing : this.clinicService.findAllOwners()) {
375	            LocalDate existingDate = existing.getRegistrationDate();
376	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
377	                count++;
378	            }
379	        }
380	        return count;
381	    }
