384	     * The number of owners that may be created on a single business day before a bulk-signup
385	     * warning is raised. Once more than this many owners already fall on the current business
386	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
387	     */
388	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
389	
390	    /**
391	     * Reports whether an unusually high number of owners have been created for today's business
392	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
393	     * the business day that {@code LocalDate.now()} rolls forward to.
394	     *
395	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
396	     */
397	    private boolean isBulkSignupDay() {
398	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
