401	    /**
402	     * Builds the customer code for a newly created owner, formatted
403	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
404	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
405	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
406	     * first eight upper-case hex characters of the SHA-256 digest of
407	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
408	     * stable for a given telephone and last name rather than dependent on creation order.
409	     *
410	     * @param postcode            the owner's postcode (may be {@code null})
411	     * @param normalizedTelephone the owner's normalized E.164 telephone
412	     * @param lastName            the owner's last name
413	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
414	     */
415	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
416	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
417	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
418	    }
419	
420	    /**
421	     * De-duplicates a freshly computed {@code base} customer code against the codes already
422	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
423	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
424	     * yields a code no existing owner holds.
425	     *
426	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
427	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
428	     */
429	    private String deduplicatedCustomerCode(String base) {
430	        Set<String> existing = new HashSet<>();
431	        for (Owner owner : this.clinicService.findAllOwners()) {
432	            if (owner.getCustomerCode() != null) {
433	                existing.add(owner.getCustomerCode());
434	            }
435	        }
436	        if (!existing.contains(base)) {
437	            return base;
438	        }
439	        int n = 2;
440	        while (existing.contains(base + "-" + n)) {
441	            n++;
442	        }
443	        return base + "-" + n;
444	    }
445	
446	    /**
447	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
448	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
449	     *
450	     * @param source the string to hash
451	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
452	     */
453	    private static String sha256Hex8(String source) {
454	        try {
455	            byte[] digest = MessageDigest.getInstance("SHA-256")
456	                .digest(source.getBytes(StandardCharsets.UTF_8));
457	            StringBuilder hex = new StringBuilder(digest.length * 2);
458	            for (byte b : digest) {
459	                hex.append(String.format("%02x", b));
460	            }
461	            return hex.substring(0, 8).toUpperCase();
462	        } catch (NoSuchAlgorithmException e) {
463	            throw new IllegalStateException("SHA-256 not available", e);
464	        }
465	    }
