501	    /**
502	     * Canonical expansions applied to common street-type abbreviations during address
503	     * normalization. Keys and values are upper-cased so the lookup runs after the address
504	     * has itself been upper-cased.
505	     */
506	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
507	        "ST", "STREET",
508	        "RD", "ROAD",
509	        "AVE", "AVENUE");
510	
511	    /**
512	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
513	     * every run of internal whitespace is collapsed to a single space, the result is
514	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
515	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
516	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
517	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
518	     * returned and compared for household duplicates; an address that is blank once
519	     * normalized fails the required-field check.
520	     *
521	     * @param address the raw address value supplied by the client
522	     * @return the normalized address (empty string when {@code address} is null or blank)
523	     */
524	    private static String normalizeAddress(String address) {
525	        if (address == null) {
526	            return "";
527	        }
528	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
529	        if (collapsed.isEmpty()) {
530	            return "";
531	        }
532	        StringBuilder normalized = new StringBuilder(collapsed.length());
533	        for (String token : collapsed.split(" ")) {
534	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
535	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
536	            if (normalized.length() > 0) {
537	                normalized.append(' ');
538	            }
539	            normalized.append(expanded != null ? expanded : token);
540	        }
541	        return normalized.toString();
542	    }
543	
544	    /**
545	     * Normalizes a last name or address for household-duplicate comparison: leading and
546	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
547	     * single space and the result is lower-cased. Two owners are considered to share a
548	     * household when both their last names and addresses produce the same key.
549	     *
550	     * @param value the raw last name or address value
551	     * @return the normalized comparison key (empty string when {@code value} is null)
552	     */
553	    private static String householdKey(String value) {
554	        if (value == null) {
555	            return "";
556	        }
557	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
558	    }
559	
560	    /**
561	     * Derives the stable shared household identifier for the given normalized last name key
562	     * and postcode. The identifier is deterministic — the same household (same
563	     * {@link #householdKey normalized} last name and postcode) always maps to the same
564	     * value — so every owner in a household is assigned an identical id. It is the
565	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
566	     * '<lastNameKey>|<postcode>'}.
567	     *
568	     * @param lastNameKey the normalized last name key
569	     * @param postcode    the owner's postcode
570	     * @return the shared household identifier
571	     */
572	    private static String householdId(String lastNameKey, String postcode) {
573	        String source = lastNameKey + "|" + postcode;
574	        try {
575	            byte[] digest = MessageDigest.getInstance("SHA-256")
576	                .digest(source.getBytes(StandardCharsets.UTF_8));
577	            StringBuilder hex = new StringBuilder(digest.length * 2);
578	            for (byte b : digest) {
579	                hex.append(String.format("%02x", b));
580	            }
581	            return hex.substring(0, 12).toUpperCase();
582	        } catch (NoSuchAlgorithmException e) {
583	            throw new IllegalStateException("SHA-256 not available", e);
584	        }
585	    }
586	
587	    /**
588	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
589	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
590	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
591	     * collides with a computed household id.
592	     *
593	     * @param owner the existing owner
594	     * @return the owner's household id, or {@code null} when it has no postcode
595	     */
596	    private static String computeHouseholdId(Owner owner) {
597	        if (owner.getPostcode() == null) {
598	            return null;
599	        }
600	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
601	    }
602	
603	    /**
604	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
605	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
606	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
607	     * when mapping a collection to size every household from a single scan.
608	     *
609	     * @param ownerDto the dto to populate
610	     * @param owner    the owner being mapped
611	     */
612	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
613	        applyMembership(ownerDto, owner, householdSizes());
614	    }
615	
616	    /**
617	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
618	     * dto using a pre-computed map of household id to member count.
619	     *
620	     * @param ownerDto       the dto to populate
621	     * @param owner          the owner being mapped
622	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
623	     */
624	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
625	        int householdSize = owner.getHouseholdId() == null ? 1
626	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
627	        int points = MembershipPoints.points(owner, householdSize);
628	        ownerDto.setMembershipPoints(points);
629	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
630	    }
631	
632	    /**
633	     * Counts how many owners belong to each household, keyed by household id. Owners without a
634	     * household id (no postcode) are excluded — such an owner is its own single-member household.
635	     *
636	     * @return a map from household id to the number of owners sharing it
637	     */
638	    private Map<String, Integer> householdSizes() {
639	        Map<String, Integer> sizes = new java.util.HashMap<>();
640	        for (Owner existing : this.clinicService.findAllOwners()) {
641	            String householdId = existing.getHouseholdId();
642	            if (householdId != null) {
643	                sizes.merge(householdId, 1, Integer::sum);
644	            }
645	        }
646	        return sizes;
647	    }
648	
649	    /**
650	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
651	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
652	     * possible duplicate when an existing owner shares its last name (compared
653	     * case-insensitively with collapsed whitespace) and its postcode while having a
654	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
655	     * existing owner's id. When several existing owners match, the one with the lowest id
656	     * is chosen so the result is deterministic. When no such owner exists — or the new
657	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
658	     * and no matching id is recorded.
659	     *
660	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
661	     */
662	    private void applyPossibleDuplicate(Owner owner) {
663	        owner.setPossibleDuplicate(false);
664	        if (owner.getPostcode() == null) {
665	            return;
666	        }
667	        String lastNameKey = householdKey(owner.getLastName());
668	        Owner match = null;
669	        for (Owner existing : this.clinicService.findAllOwners()) {
670	            if (lastNameKey.equals(householdKey(existing.getLastName()))
671	                && owner.getPostcode().equals(existing.getPostcode())
672	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
673	                if (match == null || (existing.getId() != null
674	                    && existing.getId() < match.getId())) {
675	                    match = existing;
676	                }
677	            }
678	        }
679	        if (match != null) {
680	            owner.setPossibleDuplicate(true);
681	            owner.setPossibleDuplicateOf(match.getId());
682	        }
683	    }
684	
685	    /**
686	     * Builds the derived duplicate-detection identity key from an owner's normalized
687	     * telephone, email and household id, formatted {@code
688	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
689	     * duplicates only when their whole identity keys are equal; because the telephone is
690	     * part of the key, members of the same household with different telephones produce
691	     * different keys and are both allowed.
692	     *
693	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
694	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
695	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
696	     * @return the identity key string
697	     */
698	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
699	        return (normalizedTelephone == null ? "" : normalizedTelephone)
700	            + "|" + (email == null ? "" : email)
701	            + "|" + (householdId == null ? "" : householdId);
702	    }
703	
704	    /**
705	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
706	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
707	     * {@code null} when the owner has no email.
708	     *
709	     * @param email the existing owner's stored email (may be {@code null})
710	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
711	     */
712	    private static String emailForKey(String email) {
713	        return email == null ? null : email.trim().toLowerCase();
714	    }
715	
716	    /**
717	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
718	     * and brackets are stripped. When the number already carries a leading {@code '+'}
719	     * and country code these are kept; a number written in national trunk form (a leading
720	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
721	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
722	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
723	     * after the {@code '+'}, and its national-number length must be valid for the detected
724	     * country code (see {@link #hasValidNationalLength}).
725	     *
726	     * @param telephone the raw telephone value supplied by the client
727	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
728	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
729	     */
730	    private static String toE164(String telephone) {
731	        if (telephone == null) {
732	            return null;
733	        }
734	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
735	        String digits;
736	        if (cleaned.startsWith("+")) {
737	            digits = cleaned.substring(1);
738	        } else if (cleaned.startsWith("0")) {
739	            digits = "61" + cleaned.substring(1);
740	        } else {
741	            digits = "1" + cleaned;
742	        }
743	        if (!digits.matches("[0-9]{8,15}")) {
744	            return null;
745	        }
746	        if (!hasValidNationalLength(digits)) {
747	            return null;
748	        }
749	        return "+" + digits;
750	    }
751	
752	    /**
753	     * Validates the national-number length of an E.164 digit string against its country
754	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
755	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
756	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
757	     *
758	     * @param digits the E.164 digits (without the leading {@code '+'})
759	     * @return {@code true} when the national-number length is valid for the country code
760	     */
761	    private static boolean hasValidNationalLength(String digits) {
762	        if (digits.startsWith("61")) {
763	            return digits.length() - 2 == 9;
764	        }
765	        if (digits.startsWith("1")) {
766	            return digits.length() - 1 == 10;
767	        }
768	        return true;
769	    }
770	
771	    /**
772	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
773	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
774	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
775	     */
776	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
777	        "NSW", new int[] {2000, 2099},
778	        "VIC", new int[] {3000, 3099},
779	        "QLD", new int[] {4000, 4099});
780	
781	    /**
782	     * Validates an owner's postcode for creation. A postcode is only ever validated when
783	     * present (an absent postcode is optional and accepted). When present it must be exactly
784	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
785	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
786	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
787	     *
788	     * @param postcode the supplied postcode (never {@code null} here)
789	     * @param city     the owner's city, used to derive the region
790	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
791	     *         (signalling a 400 Bad Request)
792	     */
793	    private static boolean isValidPostcode(String postcode, String city) {
794	        if (!postcode.matches("[0-9]{4}")) {
795	            return false;
796	        }
797	        int[] range = REGION_POSTCODES.get(
798	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
799	        if (range == null) {
800	            return true;
801	        }
802	        int value = Integer.parseInt(postcode);
803	        return value >= range[0] && value <= range[1];
804	    }
805	
806	    /**
807	     * Disposable email domains that are not accepted for owner creation. An owner whose
808	     * email domain (compared case-insensitively) is in this set is rejected with a 400
809	     * Bad Request.
810	     */
811	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
812	        "mailinator.com", "tempmail.com", "guerrillamail.com");
813	
814	    /**
815	     * Normalizes an owner email for creation. A present email must be a syntactically
816	     * valid address whose domain is not on the disposable-domain blocklist ({@link
817	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
818	     *
819	     * @param email the raw email value supplied by the client (never {@code null} here)
820	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
821	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
822	     */
823	    private static String normalizeEmail(String email) {
824	        String trimmed = email.trim();
825	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
826	            return null;
827	        }
828	        String normalized = trimmed.toLowerCase();
829	        String domain = normalized.substring(normalized.indexOf('@') + 1);
830	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
831	            return null;
832	        }
833	        return normalized;
834	    }
835	}
